/* Facet theme scripts — no dependencies */
(function () {
    'use strict';

    var root = document.documentElement;
    var body = document.body;

    /* ---------- Header shadow on scroll ---------- */
    var header = document.querySelector('.js-header');
    if (header) {
        var onScroll = function () { header.classList.toggle('is-scrolled', window.scrollY > 8); };
        window.addEventListener('scroll', onScroll, { passive: true });
        onScroll();
    }

    /* ---------- Mobile navigation ---------- */
    var navToggle = document.querySelector('.js-nav-toggle');
    if (navToggle) {
        var closeNav = function () {
            body.classList.remove('nav-open');
            navToggle.setAttribute('aria-expanded', 'false');
        };
        navToggle.addEventListener('click', function () {
            var open = body.classList.toggle('nav-open');
            navToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
        });
        document.addEventListener('keydown', function (e) { if (e.key === 'Escape') closeNav(); });
        window.addEventListener('resize', function () { if (window.innerWidth >= 960) closeNav(); });
        Array.prototype.forEach.call(document.querySelectorAll('.js-site-nav a[href*="#"]'), function (link) {
            link.addEventListener('click', closeNav);
        });
    }

    /* Keep aria-expanded in sync for submenus (hover/focus handled in CSS) */
    Array.prototype.forEach.call(document.querySelectorAll('.js-site-nav .has-submenu'), function (item) {
        var trigger = item.querySelector(':scope > a, :scope > .is-separator');
        if (!trigger) return;
        item.addEventListener('mouseenter', function () { trigger.setAttribute('aria-expanded', 'true'); });
        item.addEventListener('mouseleave', function () { trigger.setAttribute('aria-expanded', 'false'); });
        item.addEventListener('focusin', function () { trigger.setAttribute('aria-expanded', 'true'); });
        item.addEventListener('focusout', function (e) {
            if (!item.contains(e.relatedTarget)) trigger.setAttribute('aria-expanded', 'false');
        });
    });

    /* ---------- Light / dark toggle ---------- */
    var toggle = document.querySelector('.js-theme-toggle');
    if (toggle) {
        var currentMode = function () {
            var set = root.getAttribute('data-theme');
            if (set === 'light' || set === 'dark') return set;
            return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
        };
        toggle.addEventListener('click', function () {
            var next = currentMode() === 'dark' ? 'light' : 'dark';
            root.setAttribute('data-theme', next);
            try { localStorage.setItem('facet-theme', next); } catch (e) {}
        });
    }

    /* ---------- Search overlay ---------- */
    var searchBtn = document.querySelector('.js-search-btn');
    var searchOverlay = document.querySelector('.js-search-overlay');
    if (searchBtn && searchOverlay) {
        searchBtn.addEventListener('click', function () {
            var open = searchOverlay.hasAttribute('hidden');
            if (open) {
                searchOverlay.removeAttribute('hidden');
                var input = searchOverlay.querySelector('input');
                if (input) input.focus();
            } else {
                searchOverlay.setAttribute('hidden', '');
            }
            searchBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
        });
        document.addEventListener('keydown', function (e) {
            if (e.key === 'Escape' && !searchOverlay.hasAttribute('hidden')) {
                searchOverlay.setAttribute('hidden', '');
                searchBtn.setAttribute('aria-expanded', 'false');
                searchBtn.focus();
            }
        });
    }

    /* ---------- Media tabs ---------- */
    Array.prototype.forEach.call(document.querySelectorAll('.js-media-tabs'), function (section) {
        var tabs = Array.prototype.slice.call(section.querySelectorAll('.js-tab'));
        var panels = Array.prototype.slice.call(section.querySelectorAll('.js-panel'));
        var viewer = section.querySelector('.js-tabs-viewer');
        var current = 0;

        if (tabs.length < 2) {
            var list = section.querySelector('.media-tabs__list');
            if (list && tabs.length < 2) list.hidden = true;
        }

        function select(index, focus) {
            if (index < 0) index = tabs.length - 1;
            if (index >= tabs.length) index = 0;
            if (index === current && !focus) return;

            tabs.forEach(function (tab, i) {
                var active = i === index;
                tab.setAttribute('aria-selected', active ? 'true' : 'false');
                tab.tabIndex = active ? 0 : -1;
                if (panels[i]) {
                    if (active) {
                        panels[i].removeAttribute('hidden');
                    } else {
                        panels[i].setAttribute('hidden', '');
                        var video = panels[i].querySelector('video');
                        if (video && !video.paused) video.pause();
                    }
                }
            });

            current = index;
            if (focus) tabs[index].focus();
            tabs[index].scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'smooth' });
        }

        tabs.forEach(function (tab, i) {
            tab.addEventListener('click', function () { select(i, false); });
            tab.addEventListener('keydown', function (e) {
                if (e.key === 'ArrowRight') { e.preventDefault(); select(current + 1, true); }
                else if (e.key === 'ArrowLeft') { e.preventDefault(); select(current - 1, true); }
                else if (e.key === 'Home') { e.preventDefault(); select(0, true); }
                else if (e.key === 'End') { e.preventDefault(); select(tabs.length - 1, true); }
            });
        });

        /* Drag with mouse or swipe with finger to change tabs */
        if (viewer && tabs.length > 1) {
            var startX = null, startY = null, pointerId = null, moved = false;
            var THRESHOLD = 50;

            viewer.addEventListener('pointerdown', function (e) {
                if (e.target.closest('video') && e.pointerType === 'mouse') return; // keep video controls usable
                startX = e.clientX; startY = e.clientY; pointerId = e.pointerId; moved = false;
            });
            viewer.addEventListener('pointermove', function (e) {
                if (startX === null || e.pointerId !== pointerId) return;
                var dx = e.clientX - startX;
                if (!moved && Math.abs(dx) > 8 && Math.abs(dx) > Math.abs(e.clientY - startY)) {
                    moved = true;
                    viewer.classList.add('is-dragging');
                    try { viewer.setPointerCapture(pointerId); } catch (err) {}
                }
            });
            var end = function (e) {
                if (startX === null || e.pointerId !== pointerId) return;
                var dx = e.clientX - startX;
                if (moved && Math.abs(dx) > THRESHOLD) select(current + (dx < 0 ? 1 : -1), false);
                viewer.classList.remove('is-dragging');
                startX = startY = pointerId = null;
            };
            viewer.addEventListener('pointerup', end);
            viewer.addEventListener('pointercancel', end);
            viewer.addEventListener('dragstart', function (e) { e.preventDefault(); });
        }
    });

    /* ---------- Share popups ---------- */
    Array.prototype.forEach.call(document.querySelectorAll('.js-share'), function (link) {
        link.addEventListener('click', function (e) {
            e.preventDefault();
            window.open(link.href, 'share', 'width=600,height=560,noopener');
        });
    });

    /* ---------- Back to top ---------- */
    var backToTop = document.querySelector('.js-back-to-top');
    if (backToTop) {
        backToTop.addEventListener('click', function () {
            window.scrollTo({ top: 0, behavior: 'smooth' });
            var skip = document.querySelector('.skip-link');
            if (skip) skip.focus({ preventScroll: true });
        });
    }

    /* ---------- Statistics counter (MediaWiki siteinfo) ---------- */
    var each = function (list, fn) { Array.prototype.forEach.call(list, fn); };
    each(document.querySelectorAll('.js-stats'), function (box) {
        var cells = box.querySelectorAll('[data-stat]');
        if (!cells.length) return;
        var apis = (box.getAttribute('data-apis') || '').split(/[\s,]+/).filter(function (u) { return /^https?:\/\//.test(u); });
        var short = box.getAttribute('data-format') === 'short';
        var lang = document.documentElement.lang || undefined;
        var fmt;
        try { fmt = new Intl.NumberFormat(lang, short ? { notation: 'compact', maximumFractionDigits: 1 } : {}); }
        catch (e) { fmt = { format: function (n) { return String(n); } }; }
        var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        var key = 'facet-stats:' + apis.join('|');

        function fallback() {
            each(cells, function (c) {
                var f = c.getAttribute('data-fallback');
                c.textContent = f ? f : '—';
            });
        }
        function countUp(el, target) {
            if (reduce || !window.requestAnimationFrame) { el.textContent = fmt.format(target); return; }
            var start = null, dur = 1400;
            function step(t) {
                if (start === null) start = t;
                var p = Math.min((t - start) / dur, 1);
                var eased = 1 - Math.pow(1 - p, 3);
                el.textContent = fmt.format(Math.round(target * eased));
                if (p < 1) requestAnimationFrame(step);
            }
            requestAnimationFrame(step);
        }
        function show(totals) {
            function run() {
                each(cells, function (c) {
                    var k = c.getAttribute('data-stat');
                    if (typeof totals[k] === 'number') countUp(c, totals[k]);
                    else c.textContent = c.getAttribute('data-fallback') || '—';
                });
            }
            if (reduce || !('IntersectionObserver' in window)) { run(); return; }
            var io = new IntersectionObserver(function (entries) {
                if (entries[0].isIntersecting) { io.disconnect(); run(); }
            }, { threshold: 0.3 });
            io.observe(box);
        }

        if (!apis.length || !window.fetch) { fallback(); return; }

        var cached = null;
        try {
            var raw = sessionStorage.getItem(key);
            if (raw) { raw = JSON.parse(raw); if (Date.now() - raw.t < 3600000) cached = raw.v; }
        } catch (e) {}
        if (cached) { show(cached); return; }

        Promise.all(apis.map(function (api) {
            var url = api + (api.indexOf('?') > -1 ? '&' : '?') + 'action=query&meta=siteinfo&siprop=statistics&format=json&formatversion=2&origin=*';
            return fetch(url, { credentials: 'omit' }).then(function (r) {
                if (!r.ok) throw new Error(r.status);
                return r.json();
            }).then(function (d) {
                if (!d || !d.query || !d.query.statistics) throw new Error('no statistics');
                return d.query.statistics;
            });
        })).then(function (list) {
            var totals = {};
            list.forEach(function (st) {
                Object.keys(st).forEach(function (k) {
                    var n = Number(st[k]);
                    if (!isNaN(n)) totals[k] = (totals[k] || 0) + n;
                });
            });
            try { sessionStorage.setItem(key, JSON.stringify({ t: Date.now(), v: totals })); } catch (e) {}
            show(totals);
        }).catch(fallback);
    });

    /* ---------- Tables: scroll wrapper + header detection ---------- */
    Array.prototype.forEach.call(document.querySelectorAll('.entry__content table'), function (t) {
        // A first row made only of <th> cells, or bold-only cells, is treated as the header row
        if (!t.tHead && t.rows.length > 1) {
            var first = t.rows[0], cells = first.cells, allHead = cells.length > 0;
            for (var i = 0; i < cells.length; i++) {
                var c = cells[i], txt = c.textContent.trim(), b = c.querySelector('strong, b');
                if (!(c.tagName === 'TH' || (b && b.textContent.trim() === txt && txt))) { allHead = false; break; }
            }
            if (allHead) t.classList.add('has-header');
        }
        // Keep columns readable on small screens: wide tables scroll sideways instead of squashing
        var cols = 0;
        for (var r = 0; r < t.rows.length; r++) cols = Math.max(cols, t.rows[r].cells.length);
        if (cols > 1) t.style.setProperty('--cols', cols);
        if (t.parentNode.classList && t.parentNode.classList.contains('table-wrap')) return;
        var w = document.createElement('div');
        w.className = 'table-wrap'; w.tabIndex = 0;
        w.setAttribute('role', 'region'); w.setAttribute('aria-label', (t.caption && t.caption.textContent.trim()) || 'Table');
        t.parentNode.insertBefore(w, t); w.appendChild(t);
    });

    /* ---------- Quotes: mark a short closing line as the source ---------- */
    Array.prototype.forEach.call(document.querySelectorAll('.entry__content blockquote'), function (q) {
        var kids = q.children, last = kids[kids.length - 1];
        if (!last || kids.length < 2 || last.tagName === 'CITE' || last.tagName === 'FOOTER') return;
        if (last.tagName !== 'P') return;
        var txt = last.textContent.trim(), dash = /^[—–―-]\s*/;
        var onlyLink = last.children.length === 1 && /^(A|CITE|EM|I)$/.test(last.children[0].tagName) && last.children[0].textContent.trim() === txt;
        if (txt && txt.length <= 90 && (dash.test(txt) || onlyLink || last.querySelector('cite'))) {
            last.classList.add('quote__source');
            var w = document.createTreeWalker(last, NodeFilter.SHOW_TEXT), n;
            while ((n = w.nextNode())) { if (n.nodeValue.trim()) { n.nodeValue = n.nodeValue.replace(dash, ''); break; } }
        }
    });
})();
